    boolean hasExactAlarmAccess(){if(Build.VERSION.SDK_INT<31)return true;return ((AlarmManager)getSystemService(ALARM_SERVICE)).canScheduleExactAlarms();}
    boolean hasFullScreenAlarmAccess(){return Build.VERSION.SDK_INT<34||getSystemService(NotificationManager.class).canUseFullScreenIntent();}
    boolean openExactAlarmSettings(){try{Intent i=new Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName()));startActivity(i);return true;}catch(Exception e){Toast.makeText(this,UiStrings.t(this,"Open Settings → Apps → Mitrio → Alarms & reminders."),Toast.LENGTH_LONG).show();return false;}}
    void openFullScreenAlarmSettings(){if(Build.VERSION.SDK_INT>=34)try{startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT,Uri.parse("package:"+getPackageName())));}catch(Exception e){Toast.makeText(this,UiStrings.t(this,"Allow full-screen alarms for Mitrio in Android app settings."),Toast.LENGTH_LONG).show();}}
