    void startFirstOpenPermissions(){if(prefs.getBoolean("first_alarm_access_prompted",false)){askNotifications();return;}if(Build.VERSION.SDK_INT<31||hasExactAlarmAccess()){prefs.edit().putBoolean("first_alarm_access_prompted",true).apply();askNotifications();return;}new AlertDialog.Builder(this).setTitle(UiStrings.t(this,"Want Mitrio to ring when you choose?" )).setMessage(UiStrings.t(this,"For a reminder to ring at its set time, Android needs Alarms & reminders access. Notifications are requested separately. You can allow either now or choose Not now and set it up later." )).setCancelable(false).setNegativeButton(UiStrings.t(this,"Not now"),(d,w)->{prefs.edit().putBoolean("first_alarm_access_prompted",true).apply();askNotifications();}).setPositiveButton(UiStrings.t(this,"Set up alarm access"),(d,w)->{prefs.edit().putBoolean("first_alarm_access_prompted",true).apply();waitingForAlarmSettings=true;if(!openExactAlarmSettings()){waitingForAlarmSettings=false;askNotifications();}}).show();}
