    void offerFullScreenAccessOnFirstOpen(){if(Build.VERSION.SDK_INT<34||hasFullScreenAlarmAccess()||prefs.getBoolean("first_full_screen_prompted",false))return;prefs.edit().putBoolean("first_full_screen_prompted",true).apply();new AlertDialog.Builder(this).setTitle(UiStrings.t(this,"Show focused alarms over the lock screen?" )).setMessage(UiStrings.t(this,"Optional on newer Android phones. It lets a focused alarm open its full-screen controls. Choose Not now if notifications-only feels better; you can change this in Settings." )).setNegativeButton(UiStrings.t(this,"Not now"),null).setPositiveButton(UiStrings.t(this,"Choose full-screen access"),(d,w)->openFullScreenAlarmSettings()).show();}
