    void touchFeedback(View view){view.setOnTouchListener((v,event)->{if(!android.animation.ValueAnimator.areAnimatorsEnabled())return false;if(event.getAction()==MotionEvent.ACTION_DOWN)v.animate().scaleX(.975f).scaleY(.975f).setDuration(80).setInterpolator(new android.view.animation.DecelerateInterpolator()).start();else if(event.getAction()==MotionEvent.ACTION_UP||event.getAction()==MotionEvent.ACTION_CANCEL)v.animate().scaleX(1f).scaleY(1f).setDuration(140).setInterpolator(new android.view.animation.OvershootInterpolator(1.35f)).start();return false;});}
