    String dailyQuote(){String today=new SimpleDateFormat("yyyyMMdd",Locale.US).format(new Date());if(today.equals(prefs.getString("quote_date","")))return prefs.getString("quote_text","");String[] quotes={"A beginning can be small.","You can start from here.","One clear step is enough for now.","Progress can be quiet.","You deserve a gentle restart.","Make room for the next small thing.","Starting counts.","Your pace is allowed to be your own.","A little effort still matters.","You do not have to finish to begin.","Small actions make a path.","Try the next kind thing.","Today can hold one useful step.","You can return to what matters.","A pause does not erase your progress.","Begin with what is close.","A softer plan can still work.","Keep the first step tiny.","You can adjust as you go.","One moment at a time is a way forward.","You are allowed to begin again.","Today is not a test.","Gentle effort is real effort.","There is no perfect time to start.","Choose one thing, then breathe.","A small win is worth noticing.","Your plans can meet you where you are.","You can make the next step easier.","Rest and progress can coexist.","A fresh page is always possible."};Set<String> used=new HashSet<>(prefs.getStringSet("used_quotes",new HashSet<>()));ArrayList<Integer> choices=new ArrayList<>();for(int i=0;i<quotes.length;i++)if(!used.contains(""+i))choices.add(i);String value="";if(!choices.isEmpty()){int index=choices.get(new Random().nextInt(choices.size()));used.add(""+index);value=quotes[index];prefs.edit().putStringSet("used_quotes",used).apply();}prefs.edit().putString("quote_date",today).putString("quote_text",value).apply();return value;}
