    void wins(){section("A streak built your way","Small actions count. Honest check-ins count. Rest days don’t erase what you earned.");LinearLayout summary=card();summary.setOrientation(LinearLayout.VERTICAL);summary.setPadding(dp(18),dp(16),dp(18),dp(16));summary.setBackground(gradient(Color.rgb(247,241,252),Color.rgb(255,248,239),22));LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView flame=text("✦",34,coral,true);flame.setGravity(Gravity.CENTER);row.addView(flame,new LinearLayout.LayoutParams(dp(58),dp(64)));LinearLayout stats=column();stats.addView(text(db.currentStreak()+" day"+(db.currentStreak()==1?"":"s"),26,ink,true));stats.addView(text("current showing-up streak",12,muted,false));row.addView(stats,new LinearLayout.LayoutParams(0,-2,1));summary.addView(row);summary.addView(gap(8));summary.addView(text(db.dailyWinCount(DB.todayKey())+" sparks today  ·  "+db.totalSparks()+" earned altogether",14,purple,true));content.addView(summary);content.addView(gap(14));int[] marks={3,7,14,30};String[] badges={"First light","Steady flame","Quiet momentum","A month of showing up"};int next=30;for(int i=0;i<marks.length;i++)if(db.bestStreak()<marks[i]){next=marks[i];break;}int remaining=Math.max(0,next-db.currentStreak());LinearLayout reward=card();reward.setOrientation(LinearLayout.VERTICAL);reward.setPadding(dp(14),dp(12),dp(14),dp(12));reward.addView(text("NEXT LITTLE REWARD",10,purple,true));reward.addView(gap(4));reward.addView(text(remaining==0?"All streak badges unlocked ✨":""+remaining+" more day"+(remaining==1?"":"s")+" to unlock “"+badges[indexForMark(next)]+"”",15,ink,true));content.addView(reward);content.addView(gap(12));section("Badges","These celebrate returning, not being perfect.");for(int i=0;i<marks.length;i++){boolean unlocked=db.bestStreak()>=marks[i];LinearLayout badge=card();TextView icon=text(unlocked?"✦":"◇",19,unlocked?coral:muted,true);icon.setGravity(Gravity.CENTER);badge.addView(icon,new LinearLayout.LayoutParams(dp(38),dp(40)));LinearLayout label=column();label.addView(text(badges[i],14,ink,true));label.addView(text(marks[i]+" day personal streak"+(unlocked?"  ·  earned":"  ·  still ahead"),11,muted,false));badge.addView(label,new LinearLayout.LayoutParams(0,-2,1));content.addView(badge);content.addView(gap(7));}content.addView(text("A spark comes from finishing a task, checking in on a habit or goal, or recording an honest recovery check-in. Missing a day doesn’t remove sparks or your best streak.",12,muted,false));if(prefs.getBoolean("recovery_enabled",false)){Button recovery=smallButton("Open my private recovery check-in  →");recovery.setOnClickListener(v->{page="Recovery";build(true);});content.addView(gap(10));content.addView(recovery);}}
    int indexForMark(int mark){return mark==3?0:mark==7?1:mark==14?2:3;}
    void recovery(){
        String label=prefs.getString("recovery_label","A change I’m working on");
        section("Your private check-in","For “"+label+"”. This is your reflection space, not a medical score. A difficult day does not erase earlier progress.");
        String today=DB.todayKey(),status=db.recoveryStatus(today);
        LinearLayout panel=card();panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(14),dp(13),dp(14),dp(13));
        panel.addView(text("What feels true today?",17,ink,true));
        panel.addView(text("Any answer earns a spark for showing up honestly.",12,muted,false));
        EditText note=new EditText(this);note.setText(db.recoveryNote(today));note.setHint(UiStrings.t(this,"Optional note: what helped or made today harder?"));note.setTextColor(ink);note.setHintTextColor(muted);note.setMinLines(2);note.setMaxLines(4);note.setGravity(Gravity.TOP|Gravity.LEFT);note.setPadding(dp(12),dp(10),dp(12),dp(10));note.setBackground(shape(white,15));panel.addView(note);
        String[] labels={"I stayed with my intention","It was a mixed day","I could use support"},values={"steady","mixed","support"};
        for(int i=0;i<values.length;i++){
            final String value=values[i];Button choice=smallButton(labels[i]+(value.equals(status)?"  ✓":""));
            if(value.equals(status)){choice.setBackground(gradient(Color.rgb(229,219,244),Color.rgb(245,239,251),16));choice.setTextColor(purple);}
            choice.setOnClickListener(v->{db.saveRecoveryCheckin(DB.todayKey(),value,note.getText().toString().trim());render();Toast.makeText(this,UiStrings.t(this,"Check-in saved. You showed up for yourself ✦"),Toast.LENGTH_SHORT).show();});panel.addView(choice);
        }
        Button saveNote=smallButton("Save my private note");saveNote.setOnClickListener(v->{String current=db.recoveryStatus(DB.todayKey());if(current.isEmpty())current="note";db.saveRecoveryCheckin(DB.todayKey(),current,note.getText().toString().trim());Toast.makeText(this,UiStrings.t(this,"Note saved on this phone."),Toast.LENGTH_SHORT).show();});panel.addView(saveNote);content.addView(panel);content.addView(gap(16));
        section("Recent check-ins","Your notes and check-ins stay on this phone unless you create and move a backup.");
        Cursor history=db.recoveryHistory(7);boolean any=false;
        while(history.moveToNext()){
            any=true;String day=history.getString(0),state=history.getString(1);
            String friendly=state.equals("steady")?"Kept my intention":state.equals("support")?"Asked for support":state.equals("note")?"Private note":"Mixed day";
            LinearLayout entry=card();TextView date=text(day.equals(today)?"Today":formatDay(day),12,muted,true);entry.addView(date,new LinearLayout.LayoutParams(dp(96),dp(40)));entry.addView(text(friendly,13,ink,false));content.addView(entry);content.addView(gap(6));
        }
        history.close();if(!any)content.addView(text("No check-ins yet. Start only when it feels useful.",12,muted,false));
        Button talk=smallButton("Talk through what’s going on  →");talk.setOnClickListener(v->{Intent i=new Intent(this,TalkActivity.class);i.putExtra("starter_message","I’m working on ‘"+label+"’. I want to talk through how today feels and what would help next, without judgement. Ask me one question first.");startTalk(i);});content.addView(gap(10));content.addView(talk);
        Button clear=smallButton("Delete my recovery check-ins");clear.setTextColor(coral);clear.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(UiStrings.t(this,"Delete these private check-ins?")).setMessage(UiStrings.t(this,"This removes the recovery notes and recovery sparks from this phone. Your other tasks and rewards stay.")).setNegativeButton("Keep them",null).setPositiveButton("Delete check-ins",(d,w)->{db.clearRecoveryData();build(true);}).show());content.addView(clear);
    }
    String formatDay(String day){try{return new SimpleDateFormat("MMM d",Locale.getDefault()).format(new SimpleDateFormat("yyyyMMdd",Locale.US).parse(day));}catch(Exception e){return day;}}
