    void addGoalStarter(String title,String practice){
        if(!db.hasItem("goal",title))db.add("goal",title,0,0,false);
        if(!db.hasItem("habit",practice))db.add("habit",practice,0,0,true);
        Toast.makeText(this,UiStrings.t(this,"Added your goal and daily check-in."),Toast.LENGTH_SHORT).show();render();
    }
    void more(){
        if(settingsCategory.isEmpty()){settingsHome();return;}
        Button back=smallButton("← All settings");back.setOnClickListener(v->{settingsCategory="";build(true);});content.addView(back);content.addView(gap(8));
        switch(settingsCategory){
            case "profile": settingsProfile();break;
            case "reminders": settingsReminders();break;
            case "language": settingsLanguage();break;
            case "assistant": settingsAi();break;
            case "recovery": settingsRecovery();break;
            case "data": settingsData();break;
            default: settingsCategory="";settingsHome();break;
        }
    }
