    String backgroundLearningStatus(){if(!prefs.getBoolean("background_learning_enabled",false))return "Off. Nothing is processed in the background.";if(!prefs.getBoolean("personal_context",true))return "Paused because personal context is off. Turn that on above if you want background reflection.";String mode=prefs.getString("ai_mode",MODEL_OFF);if(mode.equals(MODEL_OFF))return "On, waiting for you to choose on-device AI.";File model=modelFile(mode);if(!model.isFile()||model.length()!=expectedModelBytes(mode))return "On, waiting for your model download to finish.";long updated=prefs.getLong("background_learning_updated",0);if(updated>0)return "Last local reflection: "+new SimpleDateFormat("EEE, MMM d · h:mm a",Locale.getDefault()).format(new Date(updated))+" · no more than once a day.";return "On. First reflection waits for Android’s charging + idle window; it may take a while.";}
