    double phoneRamGb(){ActivityManager.MemoryInfo info=new ActivityManager.MemoryInfo();((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(info);long bytes=Build.VERSION.SDK_INT>=34&&info.advertisedMem>0?info.advertisedMem:info.totalMem;return bytes/(1024d*1024d*1024d);}
