    File modelFile(String mode){File dir=getExternalFilesDir("models");if(dir==null)dir=new File(getFilesDir(),"models");if(!dir.exists())dir.mkdirs();return new File(dir,mode.equals(MODEL_SMALL)?SMALL_FILE:STANDARD_FILE);}
    File legacyStandardModelFile(){File dir=getExternalFilesDir("models");if(dir==null)dir=new File(getFilesDir(),"models");return new File(dir,LEGACY_STANDARD_FILE);}
    long expectedModelBytes(String mode){return mode.equals(MODEL_SMALL)?SMALL_BYTES:STANDARD_BYTES;}
    String expectedModelHash(String mode){return mode.equals(MODEL_SMALL)?SMALL_SHA256:STANDARD_SHA256;}
    String modelStatus(){long id=prefs.getLong("model_download_id",-1);if(id>0){String current=prefs.getString("model_download_mode",MODEL_OFF);return "Downloading "+(current.equals(MODEL_SMALL)?"the 143 MB compact model":"the 345 MB standard model")+". Your notes are not part of the download.";}String mode=prefs.getString("ai_mode",MODEL_OFF);if(mode.equals(MODEL_OFF))return "AI is off. Mitrio’s lightweight suggestions still work without a model.";File f=modelFile(mode);long expected=expectedModelBytes(mode);if(f.isFile()&&f.length()==expected)return "Ready · suggestions run on this phone, even offline.";if(f.isFile())return "The model file is incomplete. You can remove it or download it again.";if(mode.equals(MODEL_STANDARD)&&legacyStandardModelFile().exists())return "Older 614 MB model found. The new standard option is 345 MB; it replaces the old file after verification.";return "Not downloaded. Choose Download when you’re ready.";}
    void prepareSelectedModel(){
        long existing=prefs.getLong("model_download_id",-1);if(existing>0){Toast.makeText(this,UiStrings.t(this,"A model is already downloading. Cancel it before choosing another."),Toast.LENGTH_LONG).show();return;}
        String mode=prefs.getString("ai_mode",MODEL_OFF);if(mode.equals(MODEL_OFF)){Toast.makeText(this,UiStrings.t(this,"Choose a model above first."),Toast.LENGTH_SHORT).show();return;}
        File target=modelFile(mode);long expected=expectedModelBytes(mode);
        if(target.isFile()&&target.length()==expected){new Thread(()->{boolean valid=sha256(target).equals(expectedModelHash(mode));runOnUiThread(()->{if(valid){Toast.makeText(this,UiStrings.t(this,"On-device model is ready."),Toast.LENGTH_SHORT).show();build();}else{target.delete();confirmModelDownload(mode);}});}).start();return;}
        if(target.exists())target.delete();confirmModelDownload(mode);
    }
    void confirmModelDownload(String mode){String size=mode.equals(MODEL_SMALL)?"143 MB":"345 MB";boolean mobile=prefs.getBoolean("allow_mobile_model_downloads",false);String connection=mobile?"Wi-Fi or mobile data may be used.":"Wi-Fi only. Mobile data is blocked unless you allow it in this screen.";String message="Download "+size+" of model data? "+connection+"\n\nOnly the public model file is downloaded. Your notes stay on this phone.";if(mode.equals(MODEL_STANDARD)&&legacyStandardModelFile().exists())message+="\n\nAfter the new model passes its integrity check, Mitrio will remove the old 614 MB file.";new AlertDialog.Builder(this).setTitle(UiStrings.t(this,"Set up on-device AI")).setMessage(message).setNegativeButton("Not now",null).setPositiveButton("Download model",(d,w)->startModelDownload(mode)).show();}
    void startModelDownload(String mode){
        long active=prefs.getLong("model_download_id",-1);if(active>0){Toast.makeText(this,UiStrings.t(this,"A model download is already active."),Toast.LENGTH_SHORT).show();return;}
        String file=mode.equals(MODEL_SMALL)?SMALL_FILE:STANDARD_FILE;String repo=mode.equals(MODEL_SMALL)?"SmolLM2 135M":"Qwen3 0.6B INT4";String url=mode.equals(MODEL_SMALL)?"https://huggingface.co/litert-community/SmolLM2-135M-Instruct/resolve/749fc23bc8d7ef89db031d075004289c88f41c2f/SmolLM2_135M_Instruct.litertlm":"https://huggingface.co/litert-community/Qwen3-0.6B/resolve/a3c5d805ae362dff7f580bc25f2dfb9a5a7eaa76/Qwen3-0.6B_dynamic_wi4b32_afp32.litertlm";
        try{File f=modelFile(mode);if(f.exists())f.delete();DownloadManager.Request request=new DownloadManager.Request(Uri.parse(url));request.setTitle(UiStrings.t(this,"Mitrio on-device AI"));request.setDescription(repo+" · "+(mode.equals(MODEL_SMALL)?"143":"345")+" MB · your notes are not included");request.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);request.setAllowedOverMetered(prefs.getBoolean("allow_mobile_model_downloads",false));request.setAllowedOverRoaming(false);request.setDestinationInExternalFilesDir(this,"models",file);activeDownload=downloadManager.enqueue(request);prefs.edit().putLong("model_download_id",activeDownload).putString("model_download_mode",mode).putInt("model_download_schema",2).apply();build();Toast.makeText(this,UiStrings.t(this,"Model download started. You can cancel it here."),Toast.LENGTH_LONG).show();}
        catch(Exception e){Toast.makeText(this,UiStrings.t(this,"Could not start the model download. Check your connection and try again."),Toast.LENGTH_LONG).show();}
    }
    void watchModelDownload(long id){
        if(watchingDownloadId==id||verifyingDownloadId==id)return;if(downloadWatch!=null)handler.removeCallbacks(downloadWatch);watchingDownloadId=id;
        downloadWatch=new Runnable(){public void run(){if(isFinishing()||isDestroyed())return;try(Cursor c=downloadManager.query(new DownloadManager.Query().setFilterById(id))){if(c==null||!c.moveToFirst())return;int status=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(status==DownloadManager.STATUS_RUNNING||status==DownloadManager.STATUS_PENDING||status==DownloadManager.STATUS_PAUSED){long got=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR)),total=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_TOTAL_SIZE_BYTES));if(modelStatusView!=null){String text=modelStatus();if(total>0)text="Downloading · "+(got/1000000)+" / "+(total/1000000)+" MB";modelStatusView.setText(text);}handler.postDelayed(this,1200);return;}
            String mode=prefs.getString("model_download_mode",MODEL_OFF);watchingDownloadId=-1;downloadWatch=null;
            if(status==DownloadManager.STATUS_SUCCESSFUL){verifyingDownloadId=id;File f=modelFile(mode);long expectedBytes=expectedModelBytes(mode);String expectedHash=expectedModelHash(mode);new Thread(()->{boolean valid=f.isFile()&&f.length()==expectedBytes&&sha256(f).equals(expectedHash);runOnUiThread(()->{if(prefs.getLong("model_download_id",-1)==id)prefs.edit().remove("model_download_id").remove("model_download_mode").apply();verifyingDownloadId=-1;if(!valid){f.delete();Toast.makeText(MainActivity.this,"The download was incomplete or failed its integrity check. The partial file was removed; you can try again on Wi-Fi.",Toast.LENGTH_LONG).show();}else{legacyStandardModelFile().delete();LocalLearningJobService.schedule(MainActivity.this);Toast.makeText(MainActivity.this,"Model ready · it now runs offline on this phone.",Toast.LENGTH_LONG).show();}build();});}).start();
            }else{if(prefs.getLong("model_download_id",-1)==id)prefs.edit().remove("model_download_id").remove("model_download_mode").apply();if(modelStatusView!=null)modelStatusView.setText(UiStrings.t(MainActivity.this,"Download stopped. Try again when you’re ready."));if(modelDownloadButton!=null)modelDownloadButton.setText(modelButtonLabel());}
        }catch(Exception e){watchingDownloadId=-1;downloadWatch=null;prefs.edit().remove("model_download_id").remove("model_download_mode").apply();if(modelStatusView!=null)modelStatusView.setText(UiStrings.t(MainActivity.this,"Download status unavailable. You can try again."));}}};handler.postDelayed(downloadWatch,700);
    }
    void cancelModelDownload(){long id=prefs.getLong("model_download_id",-1);if(id<=0)return;String mode=prefs.getString("model_download_mode",MODEL_OFF);downloadManager.remove(id);if(downloadWatch!=null)handler.removeCallbacks(downloadWatch);watchingDownloadId=-1;downloadWatch=null;verifyingDownloadId=-1;modelFile(mode).delete();prefs.edit().remove("model_download_id").remove("model_download_mode").remove("model_download_schema").apply();if(page.equals("Settings")){build();Toast.makeText(this,UiStrings.t(this,"Download cancelled and partial file removed."),Toast.LENGTH_SHORT).show();}}
    String sha256(File f){try{MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))>0)md.update(buffer,0,n);}byte[] digest=md.digest();StringBuilder s=new StringBuilder();for(byte b:digest)s.append(String.format(Locale.US,"%02x",b&0xff));return s.toString();}catch(Exception e){return "";}}
