    void askMitrio(){
        String thought=promptInput==null?"":promptInput.getText().toString().trim();
        if(thought.isEmpty()){Toast.makeText(this,UiStrings.t(this,"Type or dictate a thought in the box above first."),Toast.LENGTH_SHORT).show();return;}
        hide();if(hasClearSleepWakeTimes(thought)){showSuggestionReview(ruleSuggestions(thought));return;}
        String mode=prefs.getString("ai_mode",MODEL_OFF);if(mode.equals(MODEL_OFF)){showSuggestionReview(ruleSuggestions(thought));return;}
        File model=modelFile(mode);if(!model.isFile()||model.length()!=expectedModelBytes(mode)){new AlertDialog.Builder(this).setTitle(UiStrings.t(this,"AI model isn’t ready yet")).setMessage("Mitrio can make a quick draft from your words now. Download the "+(mode.equals(MODEL_SMALL)?"143":"345")+" MB model in Settings if you want the optional on-device AI.").setNegativeButton("Go to Settings",(d,w)->{page="Settings";build();}).setPositiveButton("Make a quick draft",(d,w)->showSuggestionReview(ruleSuggestions(thought),"The optional AI model isn’t downloaded yet, so Mitrio made a simple draft from your words." )).show();return;}
        final String name=prefs.getString("name",""),assistantName=prefs.getString("assistant_name","Mitrio"),selectedMode=mode;
        Toast.makeText(this,UiStrings.t(this,"Local AI may make this phone feel slower for a few seconds while it thinks here for your privacy."),Toast.LENGTH_LONG).show();
        String[] cues={"Untangling one thought at a time…","Tiny plan loading. No cloud detour ✨","Your words stay here. Roll your shoulders once.","This isn’t a test. We’re making it easier to begin."};
        LinearLayout wait=column();wait.setPadding(dp(8),dp(4),dp(8),dp(4));LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);ProgressBar spinner=new ProgressBar(this,null,android.R.attr.progressBarStyleSmall);if(Build.VERSION.SDK_INT>=21)spinner.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(purple));row.addView(spinner,new LinearLayout.LayoutParams(dp(24),dp(24)));TextView cue=text(randomLine(cues),14,ink,true);LinearLayout.LayoutParams cueLp=new LinearLayout.LayoutParams(0,-2,1);cueLp.setMargins(dp(10),0,0,0);row.addView(cue,cueLp);wait.addView(row);TextView privacy=text("Your phone is doing the private brainwork. This can take a few seconds and briefly slow the device.",12,muted,false);privacy.setPadding(dp(34),dp(8),0,0);wait.addView(privacy);
        AlertDialog progress=new AlertDialog.Builder(this).setTitle(assistantName+"’s little idea studio ✨").setView(wait).setCancelable(false).create();progress.show();
        int[] cueIndex={0};Runnable cueTicker=new Runnable(){public void run(){if(!progress.isShowing()||isFinishing()||isDestroyed())return;cue.setText(UiStrings.t(MainActivity.this,cues[++cueIndex[0]%cues.length]));handler.postDelayed(this,2100);}};aiCueTicker=cueTicker;handler.postDelayed(cueTicker,2100);
        LocalAi.submit(()->{try{String result=LocalAi.suggest(model.getAbsolutePath(),selectedMode,name,assistantName,prefs.getString("ui_language","english"),prefs.getString("response_style","friendly"),thought);runOnUiThread(()->{handler.removeCallbacks(cueTicker);if(aiCueTicker==cueTicker)aiCueTicker=null;if(progress.isShowing())progress.dismiss();if(isFinishing()||isDestroyed())return;try{showSuggestionReview(parseSuggestions(result,thought));}catch(Exception e){Toast.makeText(this,assistantName+" got tangled in that one. Your words are still here—try again or add a task.",Toast.LENGTH_LONG).show();}});}catch(Exception e){runOnUiThread(()->{handler.removeCallbacks(cueTicker);if(aiCueTicker==cueTicker)aiCueTicker=null;if(progress.isShowing())progress.dismiss();if(isFinishing()||isDestroyed())return;showSuggestionReview(ruleSuggestions(thought),"The local model couldn’t finish, so Mitrio made a simple draft from your words instead." );});}});
    }
    String randomLine(String[] lines){return lines[new Random().nextInt(lines.length)];}
    static class Suggestion{String title,kind,starter;int hour=9,minute=0;boolean hasTime=false,daily=false;Suggestion(String t,String k,String s){title=t;kind=k;starter=s;}}
    boolean hasClearSleepWakeTimes(String text){
        String wake="\\b(?:wake(?:\\s+up)?|waking\\s+up|get\\s+up|getting\\s+up|be\\s+up|be\\s+awake)\\b.{0,40}?\\b(?:at|around|by)\\s+\\d{1,2}(?::\\d{2})?\\s*(?:a\\s*\\.?\\s*m\\.?|p\\s*\\.?\\s*m\\.?)?";
        String sleep="\\b(?:sleep|be\\s+asleep|fall(?:ing)?\\s+asleep|go(?:ing)?\\s+to\\s+bed)\\b.{0,40}?\\b(before|by|at)\\s+(?:midnight|\\d{1,2})(?::\\d{2})?\\s*(?:a\\s*\\.?\\s*m\\.?|p\\s*\\.?\\s*m\\.?)?";
        return java.util.regex.Pattern.compile(wake,java.util.regex.Pattern.CASE_INSENSITIVE).matcher(text).find()||java.util.regex.Pattern.compile(sleep,java.util.regex.Pattern.CASE_INSENSITIVE).matcher(text).find();
    }
    ArrayList<Suggestion> ruleSuggestions(String thought){
        ArrayList<Suggestion> out=new ArrayList<>();String normalized=thought.replace('’','\'');boolean oneTime=normalized.toLowerCase(Locale.ROOT).matches(".*\\b(today|tomorrow|once)\\b.*");
        String wakePattern="\\b(?:wake(?:\\s+up)?|waking\\s+up|get\\s+up|getting\\s+up|be\\s+up|be\\s+awake)\\b.{0,40}?\\b(?:at|around|by)\\s+(\\d{1,2})(?::(\\d{2}))?\\s*(a\\s*\\.?\\s*m\\.?|p\\s*\\.?\\s*m\\.?)?";
        java.util.regex.Matcher wake=java.util.regex.Pattern.compile(wakePattern,java.util.regex.Pattern.CASE_INSENSITIVE).matcher(normalized);
        if(wake.find()){
            int[] clock=parseClock(wake.group(1),wake.group(2),wake.group(3));
            if(clock!=null){Suggestion s=new Suggestion("Wake up at "+clockLabel(clock[0],clock[1]),"routine","");s.hour=clock[0];s.minute=clock[1];s.hasTime=true;s.daily=!oneTime;out.add(s);}
        }
        String sleepPattern="\\b(?:sleep|be\\s+asleep|fall(?:ing)?\\s+asleep|go(?:ing)?\\s+to\\s+bed)\\b.{0,40}?\\b(before|by|at)\\s+(midnight|\\d{1,2})(?::(\\d{2}))?\\s*(a\\s*\\.?\\s*m\\.?|p\\s*\\.?\\s*m\\.?)?";
        java.util.regex.Matcher sleep=java.util.regex.Pattern.compile(sleepPattern,java.util.regex.Pattern.CASE_INSENSITIVE).matcher(normalized);
        if(sleep.find()){
            String relation=sleep.group(1).toLowerCase(Locale.ROOT),timeWord=sleep.group(2);int[] clock=timeWord.equalsIgnoreCase("midnight")?new int[]{0,0}:parseClock(timeWord,sleep.group(3),sleep.group(4));
            if(clock!=null){boolean deadline=relation.equals("before")||relation.equals("by");String timeName=timeWord.equalsIgnoreCase("midnight")||clock[0]==0&&clock[1]==0?"midnight":clockLabel(clock[0],clock[1]);String title=deadline?"Be asleep before "+timeName:"Go to bed at "+timeName;Suggestion s=new Suggestion(title,deadline?"habit":"routine","");s.daily=!oneTime;if(!deadline){s.hour=clock[0];s.minute=clock[1];s.hasTime=true;}out.add(s);}
        }
        if(!out.isEmpty())return out;
        String[] parts=normalized.split("(?i)[\\n;]+|\\s+(?:and then|and also)\\s+|\\s+and\\s+(?=(?:i\\s+)?(?:need|want|have|should|must|remember|call|pay|pick|finish|do|make|go|start|sleep|wake)\\b)");
        for(String part:parts){String t=part.trim().replaceAll("^[•*\\-\\d.)\\s]+","").replaceAll("(?i)^(please\\s+)?(i\\s+)?(want\\s+to|would\\s+like\\s+to|need\\s+to|have\\s+to|should|must|remind\\s+me\\s+to|remember\\s+to|add)\\s+","").trim();if(t.isEmpty())continue;String lower=t.toLowerCase(Locale.ROOT);String kind=lower.startsWith("goal:")?"goal":lower.startsWith("habit:")?"habit":lower.startsWith("routine:")?"routine":"task";if(!kind.equals("task"))t=t.substring(t.indexOf(':')+1).trim();if(kind.equals("routine"))kind="habit";Suggestion s=new Suggestion(t,kind,"");s.daily=kind.equals("habit")&&(lower.contains("daily")||lower.contains("every day")||lower.contains("everyday"));out.add(s);}
        if(out.isEmpty())out.add(new Suggestion(thought.trim(),"task",""));return out;
    }
    int[] parseClock(String hourText,String minuteText,String ampm){try{int hour=Integer.parseInt(hourText),minute=minuteText==null?0:Integer.parseInt(minuteText);if(minute<0||minute>59)return null;if(ampm!=null){boolean pm=ampm.toLowerCase(Locale.ROOT).startsWith("p");if(hour<1||hour>12)return null;hour=hour%12+(pm?12:0);}if(hour<0||hour>23)return null;return new int[]{hour,minute};}catch(Exception e){return null;}}
    String clockLabel(int hour,int minute){int display=hour%12;if(display==0)display=12;return String.format(Locale.getDefault(),"%d:%02d %s",display,minute,hour<12?"AM":"PM");}
    ArrayList<Suggestion> parseSuggestions(String raw,String original){
        if(hasClearSleepWakeTimes(original))return ruleSuggestions(original);
        try{String trimmed=raw.trim();int start=trimmed.indexOf('{'),end=trimmed.lastIndexOf('}');if(start<0||end<start)return ruleSuggestions(original);JSONObject root=new JSONObject(trimmed.substring(start,end+1));JSONArray items=root.optJSONArray("suggestions");if(items==null||items.length()==0)return ruleSuggestions(original);ArrayList<Suggestion> out=new ArrayList<>();for(int i=0;i<Math.min(items.length(),5);i++){JSONObject o=items.optJSONObject(i);if(o==null)continue;String title=o.optString("title","").trim();if(title.isEmpty())continue;String kind=o.optString("type","task").toLowerCase(Locale.ROOT);if(!Arrays.asList("task","habit","goal","routine").contains(kind))kind="task";Suggestion s=new Suggestion(title,kind,o.optString("first_step","").trim());String tm=o.optString("time","");if(tm.matches("\\d{1,2}:\\d{2}")){String[] p=tm.split(":");s.hour=Math.min(23,Math.max(0,Integer.parseInt(p[0])));s.minute=Math.min(59,Math.max(0,Integer.parseInt(p[1])));s.hasTime=true;}if(kind.equals("routine")&&!s.hasTime){s.kind="habit";kind="habit";}s.daily=kind.equals("routine")||kind.equals("habit")&&o.optString("repeat","").equalsIgnoreCase("daily");out.add(s);}return out.isEmpty()?ruleSuggestions(original):out;}catch(Exception e){return ruleSuggestions(original);}
    }
    void showSuggestionReview(ArrayList<Suggestion> suggestions){showSuggestionReview(suggestions,null);}
    void showSuggestionReview(ArrayList<Suggestion> suggestions,String note){
        if(suggestions==null||suggestions.isEmpty()){
            Toast.makeText(this,UiStrings.t(this,"No suggestions yet. Try saying one thing you want to remember."),Toast.LENGTH_SHORT).show();
            return;
        }
        LinearLayout list=column();
        ArrayList<CheckBox> checks=new ArrayList<>();
        ArrayList<EditText> titles=new ArrayList<>();
        ArrayList<Spinner> types=new ArrayList<>();
        ArrayList<String[]> typeValues=new ArrayList<>();
        String[] allLabels={"Task","Habit","Goal","Routine"};
        String[] allValues={"task","habit","goal","routine"};
        for(Suggestion s:suggestions){
            LinearLayout card=column();card.setPadding(dp(9),dp(6),dp(9),dp(8));card.setBackground(shape(lilac,14));
            CheckBox use=new CheckBox(this);use.setText(UiStrings.t(this,"Keep this idea"));use.setChecked(true);use.setTextColor(ink);checks.add(use);card.addView(use);
            EditText title=new EditText(this);title.setSingleLine(true);title.setText(s.title);title.setTextColor(ink);title.setTextSize(14);title.setPadding(dp(8),0,dp(8),0);title.setBackground(shape(white,10));titles.add(title);card.addView(title,new LinearLayout.LayoutParams(-1,dp(44)));
            String[] choices=s.hasTime?allValues:new String[]{"task","habit","goal"};
            String[] labels=s.hasTime?allLabels:new String[]{"Task","Habit","Goal"};
            Spinner type=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,labels);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);type.setAdapter(adapter);type.setSelection(Math.max(0,Arrays.asList(choices).indexOf(s.kind)));types.add(type);typeValues.add(choices);card.addView(type);
            if(s.kind.equals("routine")&&s.daily&&s.hasTime)card.addView(text("Every day · reminder at "+clockLabel(s.hour,s.minute),12,purple,true));
            else if(s.kind.equals("habit")&&s.daily)card.addView(text("Daily check-in · no alarm",12,muted,false));
            else if(s.hasTime)card.addView(text("Reminder at "+clockLabel(s.hour,s.minute),12,muted,false));
            list.addView(card);list.addView(gap(7));
        }
        ScrollView scroll=new ScrollView(this);scroll.addView(list);
        new AlertDialog.Builder(this).setTitle(UiStrings.t(this,"Here’s what I heard")).setMessage((note==null?"":note+" ")+"Edit or untick anything that doesn’t fit. A Routine repeats daily; nothing is saved until you choose.").setView(scroll).setNegativeButton("Keep writing",null).setPositiveButton("Add selected",(d,w)->{
            int saved=0,reminders=0;
            for(int i=0;i<suggestions.size();i++){
                if(!checks.get(i).isChecked())continue;
                String title=titles.get(i).getText().toString().trim();if(title.isEmpty())continue;
                Suggestion s=suggestions.get(i);String kind=typeValues.get(i)[types.get(i).getSelectedItemPosition()];
                boolean daily=kind.equals("routine")||kind.equals("habit")&&s.daily;
                int hour=s.hasTime?s.hour:0,minute=s.hasTime?s.minute:0;
                int id=db.add(kind,title,hour,minute,daily,kind.equals("task")?s.starter:"");
                if(kind.equals("routine")){scheduleRoutine(this,id,title,hour,minute);reminders++;}
                else if(kind.equals("task")&&s.hasTime){Calendar at=Calendar.getInstance();at.set(Calendar.HOUR_OF_DAY,s.hour);at.set(Calendar.MINUTE,s.minute);at.set(Calendar.SECOND,0);if(at.getTimeInMillis()<=System.currentTimeMillis())at.add(Calendar.DAY_OF_YEAR,1);db.setReminder(id,at.getTimeInMillis());scheduleOnce(this,id,title,at.getTimeInMillis());reminders++;}
                saved++;
            }
            if(promptInput!=null)promptInput.setText(UiStrings.t(this,""));hide();build();
            String thanks=saved==0?"Nothing saved yet.":saved+" idea(s) tucked away. "+randomLine(new String[]{"Nicely untangled ✨","One less thing floating around 🌱","Future-you just got a tiny favor 💫","Plan secured. No boss battle required 🗡️"});
            Toast.makeText(this,thanks,Toast.LENGTH_LONG).show();
            if(reminders>0&&!hasExactAlarmAccess()){offerExactAlarmAccess();}else if(reminders>0&&Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED){
                new AlertDialog.Builder(this).setTitle(UiStrings.t(this,"Your reminder is saved")).setMessage(UiStrings.t(this,"Android notifications are turned off for Mitrio, so it cannot ring or appear yet. Turn them on in app settings to receive this reminder.")).setNegativeButton("Later",null).setPositiveButton("Notification settings",(dialog,which)->{Intent settings=new Intent("android.settings.APP_NOTIFICATION_SETTINGS");settings.putExtra("android.provider.extra.APP_PACKAGE",getPackageName());startActivity(settings);}).show();
            }
        }).show();
    }
    void startPrivateSpeech(){if(Build.VERSION.SDK_INT<31||!SpeechRecognizer.isOnDeviceRecognitionAvailable(this)){Toast.makeText(this,UiStrings.t(this,"This phone's installed speech service doesn't offer on-device dictation. You can type instead."),Toast.LENGTH_LONG).show();return;}if(checkSelfPermission("android.permission.RECORD_AUDIO")!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.RECORD_AUDIO"},REQUEST_MIC);return;}beginPrivateSpeech();}
    void beginPrivateSpeech(){try{if(speechRecognizer!=null)speechRecognizer.destroy();speechRecognizer=SpeechRecognizer.createOnDeviceSpeechRecognizer(this);speechRecognizer.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){Toast.makeText(MainActivity.this,"Listening on this phone…",Toast.LENGTH_SHORT).show();}public void onBeginningOfSpeech(){}public void onRmsChanged(float r){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){}public void onError(int e){Toast.makeText(MainActivity.this,"Dictation ended. You can type or try again.",Toast.LENGTH_SHORT).show();}public void onResults(Bundle b){ArrayList<String> r=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(r!=null&&!r.isEmpty()&&promptInput!=null){String old=promptInput.getText().toString().trim();promptInput.setText(old.isEmpty()?r.get(0):old+"\n"+r.get(0));}}public void onPartialResults(Bundle b){}public void onEvent(int e,Bundle b){}});Intent intent=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);intent.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);intent.putExtra(RecognizerIntent.EXTRA_PREFER_OFFLINE,true);intent.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,false);speechRecognizer.startListening(intent);}catch(Exception e){Toast.makeText(this,UiStrings.t(this,"On-device dictation isn't ready on this phone yet."),Toast.LENGTH_LONG).show();}}
    @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] results){super.onRequestPermissionsResult(requestCode,permissions,results);if(requestCode==REQUEST_MIC&&results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)beginPrivateSpeech();else if(requestCode==7)offerFullScreenAccessOnFirstOpen();}
    @Override protected void onDestroy(){if(aiCueTicker!=null){handler.removeCallbacks(aiCueTicker);aiCueTicker=null;}if(speechRecognizer!=null){speechRecognizer.destroy();speechRecognizer=null;}if(db!=null)db.close();super.onDestroy();}
    void createBackupPicker(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"Mitrio-backup-"+new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date())+".json");startActivityForResult(i,REQUEST_BACKUP);}
